body:
you could resolve right away the isRefined part, using a function that generate the function: 

``` js
function toggleRefinementBuilder(helper, facetName, isRefined) {
  if (isRefined) {
    return function() {
      helper.removeFacetRefinement(facetName, true).search();
    }
  }
  return function(){
    helper.addFacetRefinement(facetName, true).search();
  }
}
```

